type MenuFilterProviderChangeEventDetails = (
  | { reason: 'clear-press'; event: KeyboardEvent | MouseEvent | PointerEvent }
  | { reason: 'input-change'; event: Event | InputEvent }
  | { reason: 'input-clear'; event: Event | FocusEvent | InputEvent }
